class SSHChecker(object):
    @staticmethod
    def line_check(ssh, connection_alias, log_path):
        cmd = 'cat {} | grep "REST:connected"'.format(log_path)
        ssh.send_command(cmd, connection=connection_alias)
        output = ssh.read_output(connection=connection_alias)
        line = output[0]
        assert line, "Line should not be empty"

    @staticmethod
    def file_exists(ssh, connection_alias, log_path):
        cmd = "ls {}".format(log_path)
        ssh.send_command(cmd, connection=connection_alias)
        rc = ssh.get_exit_status(connection=connection_alias)
        assert rc == 0, "Command exit status was not 0"
